fn is_sorted(arr: &Vec<i32>) -> bool {
    // A single-element array is always sorted.
    if arr.len() <= 1 {
        return true;
    }
    // Check each adjacent pair for the nondecreasing property.
    for i in 1..arr.len() {
        if arr[i - 1] > arr[i] {
            return false;
        }
    }
    true
}

